// Example markets. Add or remove countries here.
// Each city needs an "area": the article is organised by these macro-areas,
// and the QA gate checks every claim against the per-area numbers.
// secondarySourceUrl is optional: an extra forecast page used to cross-check
// the data. Only use sources you are allowed to access programmatically.
const cfg = $('Set Configurations').first().json;

const countries = [
  {
    code: 'IT', name: 'Italy', language: 'Italian', locale: 'it-IT', secondarySourceUrl: '',
    cities: [
      { name: 'Milano', area: 'Nord', lat: 45.4654, lon: 9.1859 },
      { name: 'Venezia', area: 'Nord', lat: 45.4408, lon: 12.3155 },
      { name: 'Bologna', area: 'Nord', lat: 44.4949, lon: 11.3426 },
      { name: 'Firenze', area: 'Centro', lat: 43.7696, lon: 11.2558 },
      { name: 'Roma', area: 'Centro', lat: 41.9028, lon: 12.4964 },
      { name: 'Napoli', area: 'Sud', lat: 40.8518, lon: 14.2681 },
      { name: 'Bari', area: 'Sud', lat: 41.1171, lon: 16.8719 },
      { name: 'Palermo', area: 'Isole', lat: 38.1157, lon: 13.3615 },
      { name: 'Cagliari', area: 'Isole', lat: 39.2238, lon: 9.1217 }
    ]
  },
  {
    code: 'GB', name: 'United Kingdom', language: 'English', locale: 'en-GB', secondarySourceUrl: '',
    cities: [
      { name: 'London', area: 'South of England', lat: 51.5072, lon: -0.1276 },
      { name: 'Bristol', area: 'South of England', lat: 51.4545, lon: -2.5879 },
      { name: 'Birmingham', area: 'Midlands and North', lat: 52.4862, lon: -1.8904 },
      { name: 'Manchester', area: 'Midlands and North', lat: 53.4808, lon: -2.2426 },
      { name: 'Leeds', area: 'Midlands and North', lat: 53.8008, lon: -1.5491 },
      { name: 'Cardiff', area: 'Wales', lat: 51.4816, lon: -3.1791 },
      { name: 'Glasgow', area: 'Scotland', lat: 55.8642, lon: -4.2518 },
      { name: 'Edinburgh', area: 'Scotland', lat: 55.9533, lon: -3.1883 },
      { name: 'Belfast', area: 'Northern Ireland', lat: 54.5973, lon: -5.9301 }
    ]
  },
  {
    code: 'DE', name: 'Germany', language: 'German', locale: 'de-DE', secondarySourceUrl: '',
    cities: [
      { name: 'Hamburg', area: 'Norden', lat: 53.5511, lon: 9.9937 },
      { name: 'Hannover', area: 'Norden', lat: 52.3759, lon: 9.7320 },
      { name: 'Berlin', area: 'Osten', lat: 52.5200, lon: 13.4050 },
      { name: 'Leipzig', area: 'Osten', lat: 51.3397, lon: 12.3731 },
      { name: 'Köln', area: 'Westen', lat: 50.9375, lon: 6.9603 },
      { name: 'Frankfurt am Main', area: 'Westen', lat: 50.1109, lon: 8.6821 },
      { name: 'Stuttgart', area: 'Süden', lat: 48.7758, lon: 9.1829 },
      { name: 'München', area: 'Süden', lat: 48.1351, lon: 11.5820 }
    ]
  }
];

// countriesToRun (in Set Configurations) limits the run, e.g. "IT" for a single-country test.
const only = String(cfg.countriesToRun || '')
  .split(',').map(s => s.trim().toUpperCase()).filter(Boolean);

const selected = countries.filter(c => !only.length || only.includes(c.code));
if (!selected.length) {
  throw new Error(`countriesToRun ("${cfg.countriesToRun}") matches no country in Build Country List.`);
}
return selected.map(c => ({ json: c }));

// Runs once, after every country has been processed.
// It reads the country list from Build Country List, not from the loop output:
// the "done" output only carries what passed through the loop last.
const countries = $('Build Country List').all().map(i => i.json);
const now = DateTime.now();
return [{
  json: {
    runDate: now.toFormat('yyyy-MM-dd'),
    countriesProcessed: countries.length,
    countries: countries.map(c => c.code).join(', '),
    completedAt: now.toISO(),
    mode: $execution.mode
  }
}];

// One item per city, so the forecast request runs once per city.
const country = $('Loop per Country').first().json;
return country.cities.map(city => ({ json: city }));

// Turns the raw Open-Meteo responses into one compact JSON object per city.
// Only this compact structure is sent to the LLM: fewer tokens, no noise.
// Responses arrive in the same order as the city items, so index i = city i.
const cities = $('Set City List').all().map(i => i.json);
const responses = $input.all().map(i => i.json);
const country = $('Loop per Country').first().json;

// WMO weather interpretation codes, as returned by Open-Meteo.
const WMO = {
  0: 'clear sky', 1: 'mainly clear', 2: 'partly cloudy', 3: 'overcast', 45: 'fog', 48: 'fog',
  51: 'light drizzle', 53: 'drizzle', 55: 'dense drizzle', 56: 'freezing drizzle', 57: 'freezing drizzle',
  61: 'light rain', 63: 'rain', 65: 'heavy rain', 66: 'freezing rain', 67: 'freezing rain',
  71: 'light snow', 73: 'snow', 75: 'heavy snow', 77: 'snow grains',
  80: 'light rain showers', 81: 'rain showers', 82: 'violent rain showers',
  85: 'snow showers', 86: 'heavy snow showers', 95: 'thunderstorm',
  96: 'thunderstorm with hail', 99: 'thunderstorm with hail'
};
const num = (v) => (typeof v === 'number' && isFinite(v)) ? Math.round(v * 10) / 10 : null;
const at = (arr, i) => (Array.isArray(arr) ? arr[i] : undefined);

const allCitiesWeather = [];
const failedCities = [];

cities.forEach((city, idx) => {
  const d = (responses[idx] || {}).daily;
  if (!d || !Array.isArray(d.time)) {
    failedCities.push(city.name);
    return;
  }
  const days = d.time.map((date, i) => ({
    date,
    sky: WMO[at(d.weather_code, i)] || 'unknown',
    tMax: num(at(d.temperature_2m_max, i)),
    tMin: num(at(d.temperature_2m_min, i)),
    precipMm: num(at(d.precipitation_sum, i)),
    precipProb: num(at(d.precipitation_probability_max, i)),
    windMax: num(at(d.wind_speed_10m_max, i)),
    gustMax: num(at(d.wind_gusts_10m_max, i))
  }));
  allCitiesWeather.push({ ...city, days });
});

// Fail loudly: an article written from no data is worse than no article.
// The error goes to the Error Trigger at the bottom of this workflow.
if (!allCitiesWeather.length) {
  throw new Error(`No forecast data for ${country.name}: all ${cities.length} city requests failed.`);
}

return [{
  json: {
    country: country.name,
    totalCities: allCitiesWeather.length,
    failedCities,
    macroAreas: [...new Set(allCitiesWeather.map(c => c.area))],
    weatherForPrompt: allCitiesWeather.map(c => ({ city: c.name, area: c.area, days: c.days })),
    allCitiesWeather
  }
}];

// Normalises the optional secondary source.
// The HTTP node never stops the workflow, so this node always receives something:
// a page, an error object, or a 404 page with menus and headlines.
// The status code is checked first, the text length second: an error page that
// returns 200 with a few hundred characters of navigation must never be treated
// as forecast data by the verification step.
const country = $('Loop per Country').first().json;
const weatherSummary = $('Weather Analysis Chain').first().json.text || '';
const raw = $input.first().json;

const UNAVAILABLE = '[SOURCE UNAVAILABLE - do not use for verification]';
const MIN_USEFUL_CHARS = 200;

const clean = (s) => String(s)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 10000);

const extractText = (obj) => {
  if (obj === null || obj === undefined) return null;
  if (typeof obj === 'string') {
    const t = clean(obj);
    return t.length >= MIN_USEFUL_CHARS ? t : null;
  }
  if (obj.error !== undefined) return null;
  const status = obj.statusCode;
  if (typeof status === 'number' && (status < 200 || status >= 300)) return null;
  const body = obj.body !== undefined ? obj.body : (obj.data !== undefined ? obj.data : obj.html);
  if (typeof body !== 'string') return null;
  const t = clean(body);
  return t.length >= MIN_USEFUL_CHARS ? t : null;
};

const sourceConfigured = String(country.secondarySourceUrl || '').trim().length > 0;
const text = sourceConfigured ? extractText(raw) : null;

return [{
  json: {
    weatherSummary,
    secondarySource: text || UNAVAILABLE,
    sourceConfigured,
    sourcesAvailable: text ? 1 : 0,
    sourceUrl: country.secondarySourceUrl || ''
  }
}];

// Ground truth, computed in code - not by the LLM.
// One row per macro-area for TODAY, plus pre-computed "records" (windiest,
// wettest, hottest area, with ties resolved). The writer must use these for any
// superlative, and the QA step checks the article against them.
const agg = $('Aggregate Forecast Data').first().json;
const verificationReport = $input.first().json.text || '';
const weatherSummary = $('Weather Analysis Chain').first().json.text || '';

const areaOrder = [];
const areaMap = {};
for (const c of agg.allCitiesWeather) {
  if (!areaMap[c.area]) { areaMap[c.area] = []; areaOrder.push(c.area); }
  areaMap[c.area].push(c);
}

function pickRow(areaName) {
  let tMax = -999, tMin = 999, precipProb = 0, precipMm = 0, windGust = 0, windSustained = 0;
  for (const c of areaMap[areaName] || []) {
    const today = c.days && c.days[0];
    if (!today) continue;
    if (typeof today.tMax === 'number') tMax = Math.max(tMax, today.tMax);
    if (typeof today.tMin === 'number') tMin = Math.min(tMin, today.tMin);
    if (typeof today.precipProb === 'number') precipProb = Math.max(precipProb, today.precipProb);
    if (typeof today.precipMm === 'number') precipMm = Math.max(precipMm, today.precipMm);
    if (typeof today.gustMax === 'number') windGust = Math.max(windGust, today.gustMax);
    if (typeof today.windMax === 'number') windSustained = Math.max(windSustained, today.windMax);
  }
  // Open-Meteo has no official warnings. To use real warnings, add a warnings
  // feed (e.g. MeteoAlarm) and set these two fields from it: the writer, the QA
  // step and the deterministic guardrail all rely on them.
  const hasWeatherWarning = false;
  const warningType = null;

  const windKmh = windGust > 0 ? windGust : windSustained;
  let condition = 'calm';
  if (hasWeatherWarning) condition = 'warning';
  else if (precipMm > 3 || precipProb >= 60) condition = 'storm';
  else if (precipProb >= 25) condition = 'showers';
  else if (windKmh >= 50) condition = 'windy';
  else if (tMax >= 32) condition = 'hot';

  return {
    area: areaName,
    condition,
    tempRangeC: (tMin < 999 && tMax > -999) ? `${Math.round(tMin)}-${Math.round(tMax)}` : null,
    tempMaxC: tMax > -999 ? Math.round(tMax) : null,
    precipProbPercent: precipProb,
    precipMm,
    windGust,
    windKmh,
    windBasis: windKmh > 0 ? (windGust > 0 ? 'gusts' : 'sustained') : 'none',
    hasWeatherWarning,
    warningType
  };
}

const regionsData = areaOrder.map(pickRow);

function computeRecord(field) {
  const value = Math.max(...regionsData.map(r => (typeof r[field] === 'number' ? r[field] : -Infinity)));
  return { value, areas: regionsData.filter(r => r[field] === value).map(r => r.area) };
}

const groundTruthFacts = {
  strongestWind: computeRecord('windKmh'),
  highestRainProbability: computeRecord('precipProbPercent'),
  hottestArea: computeRecord('tempMaxC')
};

return [{ json: { weatherSummary, verificationReport, regionsData, groundTruthFacts } }];

// Splits the writer output into HTML and title.
// Downstream nodes only read structured fields, never the raw model text.
const raw = $json.text || '';
const country = $('Loop per Country').item.json;
const ground = $('Compute Verified Data').item.json;

const parts = raw.split('---TITLE---');
const articleHtml = parts[0].replace(/^```(?:html)?\s*/i, '').replace(/```\s*$/, '').trim();
const titleRaw = parts.length > 1 ? parts[1].trim() : '';
const h1 = articleHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
const titleFromH1 = h1 ? h1[1].replace(/<[^>]+>/g, '').trim() : '';

return {
  json: {
    countryCode: country.code,
    countryName: country.name,
    articleLanguage: country.language,
    title: titleRaw || titleFromH1 || country.name,
    articleHtml,
    regionsData: ground.regionsData,
    groundTruthFacts: ground.groundTruthFacts,
    generatedAt: DateTime.now().toISO()
  }
};

// QA passed on the first attempt: attach the verdict to the article.
const qa = $json.output || {};
const article = $('Parse Article Output').item.json;
return {
  json: {
    ...article,
    qaVerdict: qa.verdict, qaSeverity: qa.severity,
    qaIssues: qa.issues || [], qaSummary: qa.summary || '', qaRetryCount: 0
  }
};

// Deterministic guardrails, applied AFTER the LLM QA.
// An LLM reviewer can miss things. These checks need no model and cannot be
// talked out of a result:
//  1. Warning check: flags any official-warning word whose nearest area name in
//     the same sentence has no active warning in the data, and any warning
//     colour or level (the data never contains them).
//  2. House rules: flags any term from Config.bannedTerms (e.g. competitor names).
// Checks only flag. A flagged article gets FAIL + the NEEDS REVIEW banner; it is
// never silently dropped.
const cfg = $('Set Configurations').first().json;

const WARNING_WORDS = [
  'aviso', 'alerta', 'avviso', 'avvisi', 'allerta', 'allarme', 'vigilance', 'alerte',
  'warning', 'alert', 'advisory', 'warnung', 'unwetterwarnung', 'ostrzezen',
  'avertizar', 'vystrah', 'varovan', 'waarschuwing', 'weeralarm', 'varning',
  'varsel', 'advarsel', 'figyelmeztet', 'riasztas'
];
// A trailing * marks a stem; other entries must match a whole word,
// so that "red" does not catch "reduced" and "rot" does not catch "rotating".
const COLOUR_OR_LEVEL = [
  'naranja*', 'amarill*', 'rojo', 'roja', 'arancion*', 'giall*', 'rosso', 'rossa', 'orange*',
  'jaune*', 'rouge*', 'amber', 'yellow', 'red', 'gelb*', 'rot', 'rote*', 'czerwon*', 'zolt*',
  'geel', 'oranje', 'rood', 'level', 'nivel', 'niveau', 'livello', 'stufe', 'severit*'
];
// A warning word right after a negation ("without a warning", "senza allerta",
// "ohne Warnung") says the opposite and is skipped.
const NEGATIONS = [
  'sin', 'no', 'ni', 'ningun', 'ninguna', 'senza', 'non', 'nessun', 'nessuna', 'without', 'not',
  'sans', 'aucun', 'aucune', 'pas', 'ohne', 'kein', 'keine', 'keinen', 'bez', 'geen', 'zonder',
  'niet', 'utan', 'ingen', 'inga', 'uden', 'nincs', 'brak'
];

const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/ł/g, 'l').replace(/Ł/g, 'L').toLowerCase();
const esc = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordStartRe = (w) => new RegExp('(^|[^a-z])' + esc(w), 'g');
const wholeOrStemRe = (w) => w.endsWith('*')
  ? new RegExp('(^|[^a-z])' + esc(w.slice(0, -1)))
  : new RegExp('(^|[^a-z])' + esc(w) + '($|[^a-z])');

function checkWarnings(article) {
  const regions = article.regionsData || [];
  const plain = (String(article.articleHtml || '').replace(/<[^>]+>/g, ' ') + ' . ' + (article.title || ''))
    .replace(/\s+/g, ' ');
  const issues = [];
  for (const original of plain.split(/(?<=[.!?;:])\s+/)) {
    const sentence = norm(original);
    const mentions = [];
    for (const r of regions) {
      const a = norm(r.area);
      if (a.length < 4) continue;
      const re = wordStartRe(a); let m;
      while ((m = re.exec(sentence)) !== null) mentions.push({ r, pos: m.index + m[1].length });
    }
    const seen = new Set();
    for (const w of [...WARNING_WORDS].sort((a, b) => b.length - a.length)) {
      const re = wordStartRe(w); let m;
      while ((m = re.exec(sentence)) !== null) {
        const pos = m.index + m[1].length;
        if (seen.has(pos)) continue; // "alert" is also a prefix of "alerta"
        seen.add(pos);
        // Short window, so a "no" from a neighbouring clause cannot hide a real warning.
        const before = sentence.slice(Math.max(0, pos - 15), pos);
        if (NEGATIONS.some(n => wholeOrStemRe(n).test(before))) continue;
        const near = sentence.slice(Math.max(0, pos - 25), pos + w.length + 35);
        const colour = COLOUR_OR_LEVEL.find(c => wholeOrStemRe(c).test(near));
        if (colour) issues.push(`Deterministic check: a warning colour or level ("${colour.replace('*', '')}") appears in "${original.trim()}", but the data never contains warning colours or levels.`);
        if (!mentions.length) {
          if (!regions.some(r => r.hasWeatherWarning)) {
            issues.push(`Deterministic check: "${original.trim()}" mentions a weather warning ("${w}"), but no area has an active warning in the data.`);
          }
          continue;
        }
        const nearest = mentions.reduce((b, x) => Math.abs(x.pos - pos) < Math.abs(b.pos - pos) ? x : b);
        if (!nearest.r.hasWeatherWarning) {
          issues.push(`Deterministic check: "${original.trim()}" uses a warning word ("${w}") next to ${nearest.r.area}, which has no active weather warning in the data.`);
        }
      }
    }
  }
  return [...new Set(issues)];
}

function checkBannedTerms(article) {
  const terms = String(cfg.bannedTerms || '').split(',').map(t => norm(t.trim())).filter(Boolean);
  if (!terms.length) return [];
  const text = norm(String(article.articleHtml || '').replace(/<[^>]+>/g, ' ') + ' ' + (article.title || ''));
  return terms.filter(t => text.includes(t))
    .map(t => `House rule: the banned term "${t}" appears in the article.`);
}

const severityOrder = { none: 0, minor: 1, critical: 2 };

return $input.all().map(item => {
  const a = { ...item.json };
  // Fail closed: a missing verdict is never treated as PASS.
  if (a.qaVerdict !== 'PASS' && a.qaVerdict !== 'FAIL') {
    a.qaVerdict = 'FAIL';
    a.qaSeverity = 'critical';
    a.qaIssues = [...(a.qaIssues || []), 'The QA step returned no verdict.'];
  }
  const found = [...checkWarnings(a), ...checkBannedTerms(a)];
  if (found.length) {
    a.qaIssues = [...(a.qaIssues || []), ...found];
    a.qaVerdict = 'FAIL';
    if ((severityOrder[a.qaSeverity] || 0) < severityOrder.critical) a.qaSeverity = 'critical';
    a.qaSummary = `${a.qaSummary ? a.qaSummary + ' ' : ''}Deterministic guardrails: ${found.length} issue(s).`;
  }
  a.guardrailIssues = found.length;
  return { json: a };
});

parameters.text:
=The automated QA check found problems in this weather article. Rewrite it fixing ONLY the issues listed, keeping the same HTML structure, style, length and language.

ORIGINAL TITLE:
{{ $('Parse Article Output').item.json.title }}

ORIGINAL ARTICLE (HTML):
{{ $('Parse Article Output').item.json.articleHtml }}

ISSUES FOUND BY QA:
{{ JSON.stringify($json.output.issues) }}

QA SUMMARY:
{{ $json.output.summary }}

GROUND TRUTH PER MACRO-AREA (use it to correct inconsistencies):
{{ JSON.stringify($('Parse Article Output').item.json.regionsData) }}

{{ $('Set Configurations').first().json.houseRules ? 'HOUSE RULES:\n' + $('Set Configurations').first().json.houseRules : '' }}

RULES:
- Never add an official warning, a warning colour or a level for an area whose hasWeatherWarning is false. If the article already contains one, remove it and describe the real rain and wind of that area instead.
- Never add a phenomenon or event that is neither in the original article nor in the ground truth, even if a QA issue asks for it. In that case ignore that issue.
- Do not change anything that was not flagged.

Respond ONLY with the JSON: {"title": "...", "articleHtml": "..."}

parameters.jsCode:
// Keeps every field of the original article and swaps in the rewritten title and HTML.
const rewritten = $json.output || {};
const original = $('Parse Article Output').item.json;
return {
  json: {
    ...original,
    title: rewritten.title || original.title,
    articleHtml: rewritten.articleHtml || original.articleHtml,
    qaRetryCount: 1
  }
};

// Verdict of the second QA pass. If it still fails, the article is NOT dropped:
// it is published with a NEEDS REVIEW flag, so an editor sees it.
const qa = $json.output || {};
const article = $('Integrate Rewritten Content').item.json;
return {
  json: {
    ...article,
    qaVerdict: qa.verdict, qaSeverity: qa.severity,
    qaIssues: qa.issues || [], qaSummary: qa.summary || ''
  }
};

parameters.text:
=:warning: *Secondary source unreachable* - {{ $('Loop per Country').first().json.name }}
No usable content from: {{ $json.sourceUrl }}
The article is generated anyway, without the external cross-check.

=Country: {{ $('Loop per Country').first().json.name }}
Article title: {{ $json.title }}

GROUND TRUTH DATA for today, per macro-area (use it to calibrate how severe the scene may look):
{{ JSON.stringify($json.regionsData) }}

Article (HTML):
{{ $json.articleHtml }}

Write the single scene description now, in English.

parameters.jsCode:
// CMS-agnostic output. Map these fields to your CMS (WordPress, Webflow, a headless
// CMS, ...) or keep the JSON file as the hand-off format.
// Articles that failed QA are still delivered, with a visible NEEDS REVIEW banner and
// qaStatus "needs_review", so an editor can fix them instead of losing them.
const a = $('Apply Guardrails Post-QA').first().json;
const img = $input.first().json;
const cfg = $('Set Configurations').first().json;

const needsReview = a.qaVerdict !== 'PASS';
const critical = a.qaSeverity === 'critical';
const colours = critical
  ? { bg: '#FDECEA', border: '#C0392B', text: '#C0392B', icon: '⚠️' }
  : { bg: '#FEF6E0', border: '#B8860B', text: '#8A6200', icon: 'ℹ️' };
const escapeHtml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const banner = needsReview
  ? `<div style="background:${colours.bg};border:2px solid ${colours.border};border-radius:8px;padding:14px 18px;margin-bottom:1.25rem;color:${colours.text};font-weight:700;">${colours.icon} NEEDS REVIEW (QA: ${a.qaSeverity || 'critical'}) - ${escapeHtml(a.qaSummary || 'The automated check found a consistency problem.')}</div>`
  : '';

const stamp = DateTime.now().toFormat('yyyyMMdd_HHmmss');
const code = String(a.countryCode || 'xx').toLowerCase();

const payload = {
  meta: {
    brand: cfg.brandName,
    country: a.countryCode,
    language: a.articleLanguage,
    generatedAt: a.generatedAt,
    qaStatus: needsReview ? 'needs_review' : 'ok',
    qa: {
      verdict: a.qaVerdict,
      severity: a.qaSeverity || 'none',
      issues: a.qaIssues || [],
      summary: a.qaSummary || '',
      rewriteAttempts: a.qaRetryCount || 0
    },
    // Transparency: say what was AI-generated (relevant e.g. for the EU AI Act, Art. 50).
    aiGenerated: { text: true, image: !!img.imageIsAiGenerated }
  },
  content: {
    title: a.title,
    html: banner + a.articleHtml,
    image: img.imageUri || '',
    regions: a.regionsData
  }
};

return [{
  json: {
    articleKey: `${cfg.s3Prefix || ''}articles/${stamp}_${code}.json`,
    articleJson: JSON.stringify(payload, null, 2),
    countryCode: a.countryCode,
    qaStatus: payload.meta.qaStatus
  }
}];

// The Error Trigger delivers slightly different shapes depending on how the
// workflow failed (node error, crash, trigger error), so everything is read
// defensively: the notifier itself must never fail and swallow the alert.
const d = $input.first().json || {};
const wf = d.workflow || {};
const ex = d.execution || d.trigger || {};
const err = ex.error || d.error || {};

const lines = [
  ':rotating_light: *' + (wf.name || 'unknown workflow') + '* - execution failed',
  '',
  '*Node:* ' + (ex.lastNodeExecuted || 'n/a'),
  '*Error:* ' + String(err.message || 'no error message').slice(0, 800),
  '*When:* ' + DateTime.now().toFormat('yyyy-MM-dd HH:mm:ss'),
  '*Mode:* ' + (ex.mode || 'n/a')
];
if (ex.url) lines.push('', '<' + ex.url + '|Open execution in n8n>');
else if (ex.id) lines.push('', 'Execution ' + ex.id);

return [{ json: { alertText: lines.join('\n') } }];

// A run that crashes never reaches "Log Run Data", so it writes no row:
// the ABSENCE of today's row is the alarm.
// "Fetch Today's Runs" has alwaysOutputData on, so with zero rows an empty item
// still arrives here - it is filtered out before counting.
// Manual test runs are logged with mode "test" and do not count as a scheduled run.
const rows = $input.all().map(i => i.json || {}).filter(r => r.runDate);
const completed = rows.filter(r => r.mode !== 'test');
return [{
  json: {
    runMissing: completed.length === 0,
    checkedDate: DateTime.now().toFormat('yyyy-MM-dd'),
    completedText: completed.length
      ? completed.map(r => `- ${r.countriesProcessed} countries (${r.countries}), finished ${String(r.completedAt || '').slice(11, 16)}`).join('\n')
      : 'none'
  }
}];
